import csv, sqlite3
from collections import defaultdict

frpm = {}
with open('csv/frpm.csv') as f:
    for row in csv.DictReader(f):
        frpm[row['CDSCode']] = row

conn = sqlite3.connect('db/satscores.db')
cur = conn.cursor()
cur.execute('SELECT cds, AvgScrMath FROM satscores WHERE AvgScrMath IS NOT NULL')
sats = {row[0]: row[1] for row in cur.fetchall()}
conn.close()

dist_scores = defaultdict(list)
for cds, row in frpm.items():
    dist = row['District Name']
    if 'Riverside' in dist:
        if cds in sats:
            dist_scores[dist].append(sats[cds])

qualifying = [(d, sum(s)/len(s)) for d, s in dist_scores.items() if sum(s)/len(s) > 400]
print('Districts with avg SAT Math > 400:')
for d, avg in sorted(qualifying, key=lambda x: -x[1]):
    print(f'{d}: avg={avg:.2f}')

result = []
qualifying_set = {d for d, _ in qualifying}
for cds, row in frpm.items():
    dist = row['District Name']
    if dist in qualifying_set:
        funding = row.get('Charter Funding Type', '')
        result.append((row['School Name'], funding))

print(f'\nTotal schools: {len(result)}')
print('Sample:', result[:5])

